generate.final_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon (AVG(?invChange) AS ?avgChange) (SUM(?invChange) AS ?totalChange) (COUNT(?inv) AS ?recordCount)
WHERE {
  {
    SELECT ?inv ?timeHorizon (AVG(xsd:decimal(?new) - xsd:decimal(?curr)) AS ?invChange)
    WHERE {
      ?inv a wm:Investor .
      OPTIONAL { ?inv wm:timeHorizon ?timeHorizon . }
      ?inv wm:hasScenarioRebalancing ?sr .
      ?sr wm:currentAllocationPct ?curr .
      ?sr wm:newAllocationPct ?new .
      FILTER (BOUND(?curr) && BOUND(?new))
    }
    GROUP BY ?inv ?timeHorizon
  }
}
GROUP BY ?timeHorizon

